messages.content:
Generate a standalone C reproducer that triggers this vulnerability:

File: contrib/iptcutil/iptcutil.c
Line: 759
Function: chstore
Bug type: out-of-bounds-read
CWE: CWE-125
Explanation: tolower is called with a possibly negative char value (cast to int) when converting non-quoted tokens. If 'ch' has the high bit set (common with non-ASCII input and signed char), passing a negative value to tolower is undefined behavior and can cause out-of-bounds reads in ctype tables on some libc implementations. This is reachable when tokenizer is called with inflag bit 2 and input contains bytes >= 0x80. Use (unsigned char) cast before calling tolower.

Source context:
```c
      719: /* states */
      720: 
      721: #define IN_WHITE 0
      722: #define IN_TOKEN 1
      723: #define IN_QUOTE 2
      724: #define IN_OZONE 3
      725: 
      726: int _p_state;     /* current state	 */
      727: unsigned _p_flag; /* option flag	 */
      728: char _p_curquote; /* current quote char */
      729: int _p_tokpos;    /* current token pos  */
      730: 
      731: /* routine to find character in string ... used only by "tokenizer" */
      732: 
      733: static int sindex(char ch, const char *string)
      734: {
      735:     const char *cp;
      736:     for (cp = string; *cp; ++cp)
      737:         if (ch == *cp)
      738:             return (int)(cp - string); /* return position of character */
      739:     return -1;                         /* eol ... no match found */
      740: }
      741: 
      742: /* routine to store a character in a string ... used only by "tokenizer" */
      743: 
      744: static void chstore(char *string, int max, char ch)
      745: {
      746:     char c;
      747:     if (_p_tokpos >= 0 && _p_tokpos < max - 1)
      748:     {
      749:         if (_p_state == IN_QUOTE)
      750:             c = ch;
      751:         else
      752:             switch (_p_flag & 3)
      753:             {
      754:                 case 1: /* convert to upper */
      755:                     c = (char)toupper((int)ch);
      756:                     break;
      757: 
      758:                 case 2: /* convert to lower */
>>>   759:                     c = (char)tolower((int)ch);
      760:                     break;
      761: 
      762:                 default: /* use as is */
      763:                     c = ch;
      764:                     break;
      765:             }
      766:         string[_p_tokpos++] = c;
      767:     }
      768:     return;
      769: }
      770: 
      771: int tokenizer(unsigned inflag, char *token, int tokmax, char *line,
      772:               const char *white, const char *brkchar, const char *quote,
      773:               char eschar, char *brkused, int *next, char *quoted)
      774: {
      775:     int qp;
      776:     char c, nc;
      777: 
      778:     *brkused = 0; /* initialize to null */
      779:     *quoted = 0;  /* assume not quoted  */
      780: 
      781:     if (!line[*next]) /* if we're at end of line, indicate such */
      782:         return 1;
      783: 
      784:     _p_state = IN_WHITE; /* initialize state */
      785:     _p_curquote = 0;     /* initialize previous quote char */
      786:     _p_flag = inflag;    /* set option flag */
      787: 
      788:     for (_p_tokpos = 0; (c = line[*next]); ++(*next)) /* main loop */
      789:     {
      790:         if ((qp = sindex(c, brkchar)) >= 0) /* break */
      791:         {
      792:             switch (_p_state)
      793:             {
      794:                 case IN_WHITE: /* these are the same here ...	*/
      795:                 case IN_TOKEN: /* ... just get out		*/
      796:                 case IN_OZONE: /* ditto			*/
      797:                     ++(*next);
      798:                     *brkused = brkchar[qp];
      799:                     goto byebye;
```

The reproducer will be compiled with:
  clang -fsanitize=address -g -O0 -I/tmp/libtiff_upstream reproducer.c -L/tmp/libtiff_upstream/build/.libs -ltiff -lm

The project source root is: /tmp/libtiff_upstream
